        cx.run_until_parked();
        let record: RunRecord =
            serde_json::from_str(&std::fs::read_to_string(file.with_extension("json")).unwrap())
                .unwrap();
        assert!(record.marked_done && record.cancelled);

        prompt_mode.update(cx, |this, cx| {
