    /// to Spec" or "Send to Code" only while it is enabled.
    fn other_mode_button_at(
        handle: AnyWindowHandle,
        id: (&'static str, usize),
        cx: &mut TestAppContext,
    ) -> Option<String> {
        cx.update_window(handle, |_, window, cx| {
